#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char name[51];
    int id;
    double grades[5];
    double average;
    union {
        char passFail;
        int gradeCategory;
    } status;
} Student;

void inputStudentData(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        scanf("%50s", s[i].name);
        scanf("%d", &s[i].id);
        for (int j = 0; j < 5; j++) {
            scanf("%lf", &s[i].grades[j]);
        }
    }
}

void calculateAverage(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        double sum = 0.0;
        for (int j = 0; j < 5; j++) {
            sum += s[i].grades[j];
        }
        s[i].average = sum / 5.0;
    }
}

void determineStatus(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        if (s[i].average >= 85.0) {
            s[i].status.gradeCategory = 1;
        } else if (s[i].average >= 70.0) {
            s[i].status.gradeCategory = 2;
        } else if (s[i].average >= 50.0) {
            s[i].status.gradeCategory = 3;
        } else {
            s[i].status.gradeCategory = 4;
        }
    }
}

void displayStudents(const Student *s, int n) {
    for (int i = 0; i < n; i++) {
        printf("%s\n", s[i].name);
        printf("%d\n", s[i].id);
        for (int j = 0; j < 5; j++) {
            printf("%.1f", s[i].grades[j]);
            if (j < 4) printf(" ");
        }
        printf("\n");
        printf("%.1f\n", s[i].average);
        if (s[i].average >= 50.0) {
            printf("%d\n", s[i].status.gradeCategory);
        } else {
            printf("Pass/Fail - %c\n", s[i].status.passFail);
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);
    Student *students = (Student *)malloc(n * sizeof(Student));
    inputStudentData(students, n);
    calculateAverage(students, n);
    determineStatus(students, n);
    displayStudents(students, n);
    free(students);
    return 0;
}
